function feedpublisher_ai_request($f,$item,$sender=null){$e=feedpublisher_ai_config_errors($f);if($e)throw new RuntimeException($e[0]);$system=(!empty($f['ai_no_think'])?"/no_think\n":'').'Edit an RSS entry for a MyBB forum. Return only JSON with exactly two string fields in this order: title, body. Preserve facts and URLs. Never add a URL absent from the input. Use plain text or MyCode, never HTML or scripts.';if(trim($f['ai_prompt'])!=='')$system.="\nFeed-specific instructions: ".trim($f['ai_prompt']);$payload=array('model'=>trim($f['ai_model']),'temperature'=>0,'max_tokens'=>(int)$f['ai_max_tokens'],'messages'=>array(array('role'=>'system','content'=>$system),array('role'=>'user','content'=>json_encode(array('title'=>(string)$item['title'],'body'=>(string)$item['content']),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))));if(!isset($f['ai_json_mode'])||!empty($f['ai_json_mode']))$payload['response_format']=array('type'=>'json_object');if($sender)$response=call_user_func($sender,$f,$payload);else{$headers=array('Content-Type: application/json','Accept: application/json');if(!empty($f['ai_api_key']))$headers[]='Authorization: Bearer '.$f['ai_api_key'];$h=curl_init($f['ai_endpoint']);curl_setopt_array($h,array(CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_HTTPHEADER=>$headers,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>min(10,(int)$f['ai_timeout_seconds']),CURLOPT_TIMEOUT=>(int)$f['ai_timeout_seconds'],CURLOPT_MAXREDIRS=>0,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROXY=>'',CURLOPT_NOPROXY=>'*'));$body=curl_exec($h);$status=(int)curl_getinfo($h,CURLINFO_RESPONSE_CODE);$error=curl_error($h);curl_close($h);if($body===false||$status<200||$status>=300)throw new RuntimeException('AI request failed'.($error!==''?': '.feedpublisher_safe_log_text($error):' with HTTP '.$status).'.');if(strlen($body)>4194304)throw new RuntimeException('AI response exceeded 4 MiB.');$response=json_decode($body,true);}$choice=$response['choices'][0]??array();$content