function feedpublisher_ai_apply($f,$item,$sender=null){static $used=array();if(empty($f['ai_enabled']))return array('item'=>$item,'applied'=>false,'message'=>'AI cleanup disabled.');$key=(string)($f['id']??hash('sha256',($f['ai_endpoint']??'').($f['ai_model']??'')));$limit=max(1,min(10,(int)($f['ai_max_per_run']??3)));if(($used[$key]??0)>=$limit)return array('item'=>$item,'applied'=>false,'message'=>'Deterministic content kept: AI request limit reached for this run.');$used[$key]=($used[$key]??0)+1;try{$r=feedpublisher_ai_request($f,$item,$sender);$item['title']=$r['title'];$item['content']=$r['body'];return array('item'=>$item,'applied'=>true,'message'=>'Validated AI cleanup applied.');}catch(Throwable $x){return array('item'=>$item,'applied'=>false,'message'=>'Deterministic content kept: '.feedpublisher_safe_log_text($x->getMessage()));}}
